begin
  insert into auth.users(id, email) select u, u||'@test.invalid' from unnest(array[uadm,upto,ufor]) u;
  insert into core.companies(id, name, is_test) values (ca,'Альфа КВР',true);
  insert into core.company_members(company_id, user_id) values (ca,uadm),(ca,upto),(ca,ufor);
  select id into r_adm from core.company_roles where company_id=ca and template_code='company_admin';
  select id into r_pto from core.company_roles where company_id=ca and template_code='pto';
  select id into r_for from core.company_roles where company_id=ca and template_code='foreman';
  insert into core.role_assignments(company_id,user_id,role_id,project_id) values (ca,uadm,r_adm,null),(ca,upto,r_pto,null),(ca,ufor,r_for,null);
  select id into m2 from core.units where company_id is null and code = 'м²';

  reset role; perform pg_temp.as_user(uadm);
  pa := public.pf_create_project(ca, 'ЖК КВР');
  sec := public.pf_add_location(pa, null, 'building', 'Корпус Б');

  reset role; perform pg_temp.as_user(upto);
  wt := public.pf_vor_add_work_type(pa, 'Отделка (тест КВР)', m2);
  imp := public.pf_vor_create_import(pa, 'оферта.xlsx', repeat('c', 64), 'Шаблон Excel');
  n := public.pf_vor_add_rows(imp, rows);
  res := res || case when n = 57 then E'1 OK 57 строк: 16 КВР + 41 Номенклатура\n' else format(E'1 FAIL сохранено %s\n', n) end;
  select count(*) filter (where kind = 'group'), count(*) filter (where kind = 'work') into n, x from public.pf_vor_import_rows(imp);
  res := res || case when n = 16 and x = 41 then E'2 OK типы строк на сервере: group 16, work 41\n' else format(E'2 FAIL group %s work %s\n', n, x) end;
  select count(*) into n from public.pf_vor_import_rows(imp) where kind = 'work' and (context ->> 'kvr') is not null;
  res := res || case when n = 41 then E'3 OK у каждой строки Номенклатуры есть ссылка на КВР (context.kvr)\n' else format(E'3 FAIL ссылок %s\n', n) end;
  select count(*) into n from public.pf_vor_import_rows(imp) where kind = 'work' and context ->> 'note' like 'Пояснение %';
  res := res || case when n = 35 then E'4 OK пояснения сохранены (35 строк с «Комментарием»)\n' else format(E'4 FAIL пояснений %s\n', n) end;
  -- решения: все работы → Корпус Б, один вид работ, м² (ЕИ для подтверждения не важна)
  perform public.pf_vor_resolve_rows(imp, (select jsonb_agg(jsonb_build_object('row_no', row_no, 'location_id', sec, 'work_type_id', wt, 'unit_id', m2, 'match', 'green')) from public.pf_vor_import_rows(imp) where kind = 'work'));
  n := public.pf_vor_confirm(imp);
  res := res || case when n = 41 then E'5 OK подтверждение: 41 позиция (КВР позиций нет)\n' else format(E'5 FAIL позиций %s\n', n) end;
  select count(*), sum(qty) into n, x from public.pf_vor_positions(pa, null) where import_id = imp;
  select sum(qty) into y from public.pf_vor_import_rows(imp) where kind = 'work';
  res := res || case when n = 41 and x = y and x = 160015.28 then E'6 OK Σ позиций = Σ Номенклатуры = 160 015,28 (без задвоения)\n' else format(E'6 FAIL позиций %s Σ %s / %s\n', n, x, y) end;
  reset role;
  select count(*) into n from planfact.vor_links l join planfact.vor_source_rows s on s.id = l.source_row_id where s.import_id = imp and s.kind <> 'work';
  res := res || case when n = 0 then E'7 OK связки только со строками Номенклатуры\n' else format(E'7 FAIL связок с КВР %s\n', n) end;

  perform pg_temp.as_user(ufor);
  select count(*), sum(plan_qty) into n, x from public.pf_fact_positions(pa, sec);
  res := res || case when n = 41 and x = 160015.28 then E'8 OK прораб: 41 позиция, план 160 015,28 — КВР в факт не попал\n' else format(E'8 FAIL факт: %s / %s\n', n, x) end;
  select count(*) into n from public.pf_vor_import_rows(imp) where kind = 'work' and name = 'Работа «Вид 13»' and context ->> 'note' in ('Пояснение 17', 'Пояснение 18');
  res := res || case when n = 2 then E'9 OK прораб видит две одноимённые работы с разными пояснениями\n' else format(E'9 FAIL %s\n', n) end;
  reset role;
  raise exception E'ОТЧЁТ (откат):\n%\nFAIL всего: %', res, (length(res) - length(replace(res,'FAIL','')))/4;
end $$;
